// evalSpec pins what a case starts from and what judges it, which is what
// turns a record of past runs into something re-executable.
func evalSpec(ctx context.Context, s *store.Store, args []string) error {
	f := flag.NewFlagSet("eval spec", flag.ContinueOnError)
	caseID := f.String("case", "", "evaluation case ID")
	fixture := f.String("fixture", "", "repository the task starts from")
	ref := f.String("ref", "", "commit or branch pinning the fixture")
	criteria := f.String("criterion", "", "comma-separated type=value completion criteria, or type@kind=value to demand a kind of proof")
	gateType := f.String("gate-type", "", "criterion the gate measures")
	gateCommand := f.String("gate-command-json", "", "JSON command array for the gate")
	gateValue := f.String("gate-success-value", "true", "value the gate must reach")
	gateKind := f.String("gate-kind", "", "what the gate establishes: "+strings.Join(policy.KnownGateKinds(), ", "))
	seedTitle := f.String("work", "", "seed the trial's backlog with this work item (repeatable via comma separation)")
	seedScope := f.String("work-scope", "", "declared change scope for the seeded work")
	tokens := f.Int64("token-budget", 0, "token ceiling for one trial")
	cost := f.Float64("cost-budget-usd", 0, "cost ceiling for one trial")
	timeout := f.Int("timeout-seconds", 0, "wall-clock ceiling for one trial")
	if err := f.Parse(args); err != nil {
		return err
	}
	if *caseID == "" || *fixture == "" {
		return errors.New("--case and --fixture are required")
	}
	p, err := currentProject(ctx, s)
	if err != nil {
		return err
	}
	spec, err := s.CaseSpec(ctx, p.ID, *caseID)
	if err != nil {
		return err
	}
	absolute, err := filepath.Abs(*fixture)
	if err != nil {
		return err
	}
	spec.Fixture, spec.Ref = absolute, *ref
	spec.TokenBudget, spec.CostBudgetUSD, spec.TimeoutSeconds = *tokens, *cost, *timeout
	for _, pair := range splitList(*criteria) {
		// The same syntax the product uses, so a case can demand that a
		// feature be exercised rather than merely compiled — and so both arms
		// of a comparison are judged by that demand.
		criterion, parseErr := model.ParseCriterion(pair)
		if parseErr != nil {
			return parseErr
		}
		spec.Criteria = append(spec.Criteria, evaluation.Criterion{Type: criterion.Type,
			ExpectedValue: criterion.ExpectedValue, RequiredKind: criterion.RequiredKind})
	}
	for _, title := range splitList(*seedTitle) {
		spec.SeedWork = append(spec.SeedWork, evaluation.SeedWorkItem{Title: title, ChangeScope: *seedScope, Priority: 50})
	}
	if *gateType != "" {
		var command []string
		if err = json.Unmarshal([]byte(*gateCommand), &command); err != nil {
			return fmt.Errorf("decode --gate-command-json: %w", err)
		}
		if err = policy.ValidateCommand(command); err != nil {
			return fmt.Errorf("gate command rejected: %w", err)
		}
		if err = policy.ValidGateKind(*gateKind); err != nil {
			return err
		}
		spec.Gates = append(spec.Gates, evaluation.Gate{Type: *gateType, Command: command, Required: true,
			SuccessValue: *gateValue, Kind: *gateKind})
	}
	// The clean state is recorded from the fixture as it stands now, so a
	// later trial starting from anything else is detectable.
	if spec.Ref != "" {
		if _, err = gitops.HeadCommit(ctx, absolute, spec.Ref); err != nil {
			return fmt.Errorf("pin %s in %s: %w", spec.Ref, absolute, err)
		}
	}
	if err = s.SaveCaseSpec(ctx, *caseID, spec); err != nil {
		return err
	}
	fmt.Printf("case pinned: %s fixture=%s ref=%s criteria=%d gates=%d seed_work=%d\n",
		*caseID, spec.Fixture, orNone(spec.Ref), len(spec.Criteria), len(spec.Gates), len(spec.SeedWork))
	if len(spec.SeedWork) == 0 {
		fmt.Println("  note: 초기 작업이 없으면 이 케이스는 구현뿐 아니라 목표 분해까지 측정합니다 (--work 로 고정 가능)")
	}
	if len(spec.Criteria) == 0 {
		fmt.Println("  warning: 완료 조건이 없으면 시행을 판정할 수 없습니다 (--criterion type=value)")
	}
	return nil
}

func orNone(value string) string {
	if value == "" {
		return "(default branch)"
	}
	t.Setenv("GOALFORGE_DB", filepath.Join(t.TempDir(), "state.db"))
	t.Chdir(repo)

	runCLI(t, ctx, "project", "init", "--name", "evidence", "--provider", "claude", "--model", "haiku", "--worktrees", "--auto-commit")

	// Readiness must refuse a project that could never complete, before any
	// model call is spent on it. The fake provider cannot satisfy the adapter
	// flag check, so the readiness findings are asserted directly rather than
	// through the overall verdict.
	runCLI(t, ctx, "goal", "set", "--title", "greeting", "--objective", "write hello.txt",
		"--criterion", "build_passed=true", "--criterion", "latency_p95=200")
	noGates, err := runCLIWithError(t, ctx, "doctor")
	if err == nil || !strings.Contains(noGates, "검증 게이트가 없어") {
		t.Fatalf("doctor must block a project with no gates:\n%s", noGates)
	}
	runCLI(t, ctx, "verify", "gate", "add", "--type", "build_passed",
		"--command-json", `["`+strings.ReplaceAll(gate, `\`, `\\`)+`"]`, "--timeout-seconds", "30")
	unmeasurable, err := runCLIWithError(t, ctx, "doctor")
	if err == nil || !strings.Contains(unmeasurable, "criteria coverage") || !strings.Contains(unmeasurable, "latency_p95") {
		t.Fatalf("doctor must name the criterion nothing measures:\n%s", unmeasurable)
	}
	// Dropping the unmeasurable criterion is a goal change, and the readiness
	// finding has to clear once every criterion has a gate.
	runCLI(t, ctx, "goal", "set", "--title", "greeting", "--objective", "write hello.txt",
		"--criterion", "build_passed=true", "--reason", "측정할 수 없는 조건 제거")
	covered, _ := runCLIWithError(t, ctx, "doctor")
	if !strings.Contains(covered, "OK   criteria coverage") {
		t.Fatalf("criteria coverage should clear:\n%s", covered)
	}

	// The preview refuses before there is work, and explains itself once
	// there is.
	if output, err := runCLIWithError(t, ctx, "plan"); err == nil {
		t.Fatalf("plan must refuse with no work item:\n%s", output)
	}
	workOut := runCLI(t, ctx, "work", "add", "--title", "create hello.txt", "--priority", "10", "--scope", "hello.txt")
	workID := regexp.MustCompile(`WORK-\d+`).FindString(workOut)
	planOut := runCLI(t, ctx, "plan")
	for _, expected := range []string{workID, "다음 작업", "forecast", "model"} {
		if !strings.Contains(planOut, expected) {
			t.Fatalf("plan output missing %q:\n%s", expected, planOut)
		}
	}
	// Previewing must not consume the work it previews.
	if !strings.Contains(runCLI(t, ctx, "work", "list"), "BACKLOG") {
		t.Fatalf("the preview claimed the work item:\n%s", runCLI(t, ctx, "work", "list"))
	}

	runCLI(t, ctx, "decision", "add", "--title", "단일 파일 출력",
		"--decision", "결과는 hello.txt 하나로 쓴다", "--alternatives", "여러 파일: 검증이 복잡해짐")
	if !strings.Contains(runCLI(t, ctx, "decision", "list"), "단일 파일 출력") {
		t.Fatal("recorded decision is not listed")
	}

	continueOut := runCLI(t, ctx, "continue")
	if !strings.Contains(continueOut, "passed=true") {
		t.Fatalf("continue output:\n%s", continueOut)
	}
	runID := regexp.MustCompile(`RUN-\d+`).FindString(continueOut)

	// Status reports the criterion with the evidence that decided it.
	statusOut := runCLI(t, ctx, "status")
	if !strings.Contains(statusOut, "[v]") || !strings.Contains(statusOut, "build_passed") {
		t.Fatalf("status must show the criterion verdict:\n%s", statusOut)
	}

	// A reproduction package is assembled from a real run.
	reproDir := filepath.Join(t.TempDir(), "repro")
	runCLI(t, ctx, "reproduce", "--run", runID, "--out", reproDir)
	for _, name := range []string{"reproduction.json", "reproduce.sh", "gate-output.log"} {
		if _, err := os.Stat(filepath.Join(reproDir, name)); err != nil {
			t.Fatalf("reproduction package missing %s: %v", name, err)
		}
	}

	// Merging leaves the default branch unverified until integration runs,
	// and that must be visible in status rather than only in the database.
	runCLI(t, ctx, "approval", "request", "--action", "merge-branch", "--work-item", workID, "--reason", "e2e")
	approvalID := regexp.MustCompile(`APR-\d+`).FindString(runCLI(t, ctx, "approval", "list"))
	if approvalID == "" {
		t.Fatal("no pending approval to approve")
	}
	runCLI(t, ctx, "approval", "approve", approvalID)
	mergeOut := runCLI(t, ctx, "merge", "--work-item", workID)
	if !strings.Contains(mergeOut, "integration verification required") {
		t.Fatalf("merge must ask for integration verification:\n%s", mergeOut)
	}
	if !strings.Contains(runCLI(t, ctx, "status"), "통합 검증 필요") {
		t.Fatalf("status must surface the integration gap:\n%s", runCLI(t, ctx, "status"))
	}
	integrationOut := runCLI(t, ctx, "verify", "integration")
	// The required gates passing is what "integration" means; whether the goal
	// is finished is the completion criteria, which the same run measures and
	// reports separately.
	if !strings.Contains(integrationOut, "필수 게이트 통과") {
		t.Fatalf("integration verification:\n%s", integrationOut)
	}
	if !strings.Contains(integrationOut, "완료 조건") {
		t.Fatalf("the run must say where the completion criteria stand:\n%s", integrationOut)
	}
	if verified := runCLI(t, ctx, "status"); !strings.Contains(verified, "[v]") {
		t.Fatalf("integration evidence should satisfy the criterion:\n%s", verified)
	}

	// AT-10: changing the code the integration check measured must invalidate
	// its evidence. Relying on each mutation site to declare that is how
	// evidence outlives the thing it describes.
	if err := os.WriteFile(filepath.Join(repo, "unverified.go"), []byte("package main\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	stale := runCLI(t, ctx, "status")

func (s *Store) SetGoal(ctx context.Context, projectID, title, objective, reason string, criteria []model.Criterion) (model.Goal, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return model.Goal{}, err
	}
	defer tx.Rollback()
	var version int
	if err = tx.QueryRowContext(ctx, `SELECT COALESCE(MAX(version),0)+1 FROM goals WHERE project_id=?`, projectID).Scan(&version); err != nil {
		return model.Goal{}, err
	}
	if version > 1 && strings.TrimSpace(reason) == "" {
		return model.Goal{}, errors.New("change reason is required for a new goal version")
	}
	g := model.Goal{ID: NewID("GOAL"), ProjectID: projectID, Version: version, Title: title, Objective: objective, Status: "ACTIVE", ChangeReason: reason, CreatedAt: time.Now().UTC(), Criteria: criteria}
	if _, err = tx.ExecContext(ctx, `UPDATE goals SET status='SUPERSEDED' WHERE project_id=? AND status='ACTIVE'`, projectID); err != nil {
		return g, err
	}
	if _, err = tx.ExecContext(ctx, `INSERT INTO goals(id,project_id,version,title,objective,status,change_reason,created_at) VALUES(?,?,?,?,?,?,?,?)`, g.ID, g.ProjectID, g.Version, g.Title, g.Objective, g.Status, g.ChangeReason, g.CreatedAt.Format(time.RFC3339Nano)); err != nil {
		return g, err
	}
	for _, c := range criteria {
		if kindErr := policy.ValidGateKind(c.RequiredKind); kindErr != nil {
			return g, fmt.Errorf("criterion %s: %w", c.Type, kindErr)
		}
		if _, err = tx.ExecContext(ctx, `INSERT INTO goal_criteria(goal_id,criterion_type,expected_value,required_kind) VALUES(?,?,?,?)`, g.ID, c.Type, c.ExpectedValue, strings.ToLower(strings.TrimSpace(c.RequiredKind))); err != nil {
			return g, err
		}
	}
	if _, err = tx.ExecContext(ctx, `UPDATE projects SET state='READY' WHERE id=?`, projectID); err != nil {
		return g, err
	}
	return g, tx.Commit()
}

func (s *Store) CurrentGoal(ctx context.Context, projectID string) (model.Goal, error) {
	return s.loadGoal(ctx, `SELECT id,project_id,version,title,objective,status,change_reason,created_at FROM goals WHERE project_id=? AND status='ACTIVE' ORDER BY version DESC LIMIT 1`, projectID)
}

func (s *Store) LatestGoal(ctx context.Context, projectID string) (model.Goal, error) {
	return s.loadGoal(ctx, `SELECT id,project_id,version,title,objective,status,change_reason,created_at FROM goals WHERE project_id=? ORDER BY version DESC LIMIT 1`, projectID)
}

func (s *Store) loadGoal(ctx context.Context, query, projectID string) (model.Goal, error) {
	var g model.Goal
	var created string
	err := s.db.QueryRowContext(ctx, query, projectID).
		Scan(&g.ID, &g.ProjectID, &g.Version, &g.Title, &g.Objective, &g.Status, &g.ChangeReason, &created)
	if errors.Is(err, sql.ErrNoRows) {
		return g, ErrNotFound
	}
	if err != nil {
		return g, err
	}
	g.CreatedAt, _ = time.Parse(time.RFC3339Nano, created)
	rows, err := s.db.QueryContext(ctx, `SELECT criterion_type,expected_value,COALESCE(required_kind,'') FROM goal_criteria WHERE goal_id=? ORDER BY criterion_type`, g.ID)
	if err != nil {
		return g, err
	}
	defer rows.Close()
	for rows.Next() {
		var c model.Criterion
		if err = rows.Scan(&c.Type, &c.ExpectedValue, &c.RequiredKind); err != nil {
			return g, err
		}
		g.Criteria = append(g.Criteria, c)
	}
	return g, rows.Err()
}

